package com.bank.kyc.model;

import jakarta.persistence.*;
import java.time.LocalDateTime;

@Entity
@Table(name = "customer_kyc")
public class CustomerKyc {

    @Id
    @Column(name = "kyc_id")
    private String kycId;

    @Column(name = "customer_id", nullable = false, unique = true)
    private String customerId;

    @Column(name = "full_name", nullable = false)
    private String fullName;

    @Column(name = "pan_number", nullable = false, unique = true)
    private String panNumber;

    @Column(name = "aadhaar_hash")
    private String aadhaarHash;

    @Column(nullable = false)
    private String status;

    @Column(name = "verified_at")
    private LocalDateTime verifiedAt;

    @Column(name = "created_at")
    private LocalDateTime createdAt;

    protected CustomerKyc() {}

    public CustomerKyc(String kycId, String customerId, String fullName, String panNumber) {
        this.kycId = kycId;
        this.customerId = customerId;
        this.fullName = fullName;
        this.panNumber = panNumber;
        this.status = "PENDING";
        this.createdAt = LocalDateTime.now();
    }

    public void verify() {
        this.status = "VERIFIED";
        this.verifiedAt = LocalDateTime.now();
    }

    public void reject(String reason) { this.status = "REJECTED"; }

    public String getKycId() { return kycId; }
    public String getCustomerId() { return customerId; }
    public String getFullName() { return fullName; }
    public String getPanNumber() { return panNumber; }
    public String getStatus() { return status; }
    public LocalDateTime getVerifiedAt() { return verifiedAt; }
}
