package com.bank.kyc.repository;

import com.bank.kyc.model.CustomerKyc;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.jdbc.AutoConfigureTestDatabase;
import org.springframework.boot.test.autoconfigure.orm.jpa.DataJpaTest;
import org.springframework.boot.testcontainers.service.connection.ServiceConnection;
import org.testcontainers.containers.PostgreSQLContainer;
import org.testcontainers.junit.jupiter.Container;
import org.testcontainers.junit.jupiter.Testcontainers;
import static org.assertj.core.api.Assertions.*;

@DataJpaTest  // loads JPA layer only
@Testcontainers
@AutoConfigureTestDatabase(replace = AutoConfigureTestDatabase.Replace.NONE)
@DisplayName("Customer KYC Repository — JPA Tests with Testcontainers")
class CustomerKycRepositoryTest {

    @Container
    @ServiceConnection  // Spring Boot 3.1+ auto-wires datasource from container
    static PostgreSQLContainer<?> postgres = new PostgreSQLContainer<>("postgres:16-alpine");

    @Autowired CustomerKycRepository kycRepo;

    @BeforeEach
    void setUp() {
        kycRepo.deleteAll();
        kycRepo.save(new CustomerKyc("KYC-001", "CUST001", "Rajesh Kumar", "ABCDE1234F"));
    }

    @Test
    @DisplayName("should find KYC by customer ID")
    void shouldFindByCustomerId() {
        var kyc = kycRepo.findByCustomerId("CUST001");
        assertThat(kyc).isPresent();
        assertThat(kyc.get().getFullName()).isEqualTo("Rajesh Kumar");
    }

    @Test
    @DisplayName("should detect existing PAN number")
    void shouldDetectExistingPan() {
        assertThat(kycRepo.existsByPanNumber("ABCDE1234F")).isTrue();
        assertThat(kycRepo.existsByPanNumber("ZZZZZ9999Z")).isFalse();
    }

    @Test
    @DisplayName("should enforce unique PAN constraint")
    void shouldRejectDuplicatePan() {
        assertThatThrownBy(() ->
            kycRepo.save(new CustomerKyc("KYC-002", "CUST002", "Priya", "ABCDE1234F")))
            .isInstanceOf(Exception.class); // DataIntegrityViolationException
    }
}
