package com.bank.kyc.integration;

import com.bank.kyc.dto.KycResponse;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.web.client.TestRestTemplate;
import org.springframework.boot.testcontainers.service.connection.ServiceConnection;
import org.springframework.http.*;
import org.testcontainers.containers.PostgreSQLContainer;
import org.testcontainers.junit.jupiter.Container;
import org.testcontainers.junit.jupiter.Testcontainers;
import static org.assertj.core.api.Assertions.*;

@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
@Testcontainers
@DisplayName("KYC Service — Full Integration Tests")
class KycIntegrationTest {

    @Container
    @ServiceConnection
    static PostgreSQLContainer<?> postgres = new PostgreSQLContainer<>("postgres:16-alpine");

    @Autowired TestRestTemplate restTemplate;

    @Test
    @DisplayName("full flow: submit → verify → get")
    void shouldCompleteFullKycFlow() {
        // Submit
        String submitBody = """
            {"customerId":"CUST099","fullName":"Test User","panNumber":"TSTPN9999Z"}
            """;
        ResponseEntity<KycResponse> submitResp = restTemplate.postForEntity(
            "/api/v1/kyc", createJsonRequest(submitBody), KycResponse.class);
        assertThat(submitResp.getStatusCode()).isEqualTo(HttpStatus.CREATED);
        assertThat(submitResp.getBody().status()).isEqualTo("PENDING");

        // Verify
        ResponseEntity<KycResponse> verifyResp = restTemplate.exchange(
            "/api/v1/kyc/CUST099/verify", HttpMethod.PUT, null, KycResponse.class);
        assertThat(verifyResp.getBody().status()).isEqualTo("VERIFIED");

        // Get
        ResponseEntity<KycResponse> getResp = restTemplate.getForEntity(
            "/api/v1/kyc/CUST099", KycResponse.class);
        assertThat(getResp.getBody().status()).isEqualTo("VERIFIED");
    }

    private HttpEntity<String> createJsonRequest(String body) {
        HttpHeaders headers = new HttpHeaders();
        headers.setContentType(MediaType.APPLICATION_JSON);
        return new HttpEntity<>(body, headers);
    }
}
